static Status open_all(const std::filesystem::path&r,ObjectStore*s,Ledger*l,GraphState*g){auto st=object_store_open(r/"objects",s);if(st!=Status::Ok)return st;if((st=ledger_open(r/"ledger"/"events.lgl",l))!=Status::Ok)return st;return graph_replay(s,*l,g);}static Status write_bytes(const std::filesystem::path&p,ByteSpan b){std::error_code ec;std::filesystem::create_directories(p.parent_path(),ec);if(ec)return Status::IOError;std::ofstream f(p,std::ios::binary|std::ios::trunc);if(!f)return Status::IOError;if(b.size)f.write((const char*)b.data,(std::streamsize)b.size);return f?Status::Ok:Status::IOError;}static Status materialize(const std::filesystem::path&r,const ObjectStore&s,const GraphState&g,const Digest256&canon,const Digest256&proof){std::error_code ec;std::filesystem::create_directories(r/"projection",ec);std::filesystem::create_directories(r/"views",ec);if(ec)return Status::IOError;Digest256 root{};graph_root(g,&root);std::string summary="graph_root="+hex(root)+"\nnodes="+std::to_string(g.nodes.size())+"\nedges="+std::to_string(g.edges.size())+"\n";if(write_bytes(r/"projection"/"graph.txt",{(const u8*)summary.data(),(u64)summary.size()})!=Status::Ok)return Status::IOError;Buffer b;if(object_get(&s,canon,&b)!=Status::Ok)return Status::ObjectNotFound;if(write_bytes(r/"views"/"canon.view",{b.data(),(u64)b.size()})!=Status::Ok)return Status::IOError;if(object_get(&s,proof,&b)!=Status::Ok)return Status::ObjectNotFound;return write_bytes(r/"views"/"proof.view",{b.data(),(u64)b.size()});}
Status verify_root(const std::filesystem::path&r,Digest256*gr,Digest256*cv,Digest256*pv){ObjectStore s{};Ledger l{};GraphState g{};auto st=open_all(r,&s,&l,&g);if(st!=Status::Ok)return st;if((st=graph_root(g,gr))!=Status::Ok)return st;if((st=compile_canon_view(&g,&s,&l,cv))!=Status::Ok)return st;if((st=compile_proof_view(&g,&s,&l,"IMP-GENESIS-MVS-001",pv))!=Status::Ok)return st;return materialize(r,s,g,*cv,*pv);}static Status add_controlled_claim(ObjectStore*s,Ledger*l,GraphState*g,std::string_view id,u64 value,std::string_view scope,std::string_view prov){LgoBuilder b{};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::CLAIM);lgo_add_utf8(&b,F_SEMANTIC_ID,id);lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_u64(&b,F_EPISTEMIC_STATE,(u64)Epistemic::TESTED);lgo_add_utf8(&b,F_SCOPE,scope);lgo_add_u64(&b,F_VALUE_U64,value);lgo_add_utf8(&b,F_CLAIM_CLASS,"CONTROLLED_COURT");lgo_add_utf8(&b,F_PROVENANCE_ID,prov);lgo_add_utf8(&b,F_TIME_SCOPE,"MEVS-fixture-v1");lgo_add_utf8(&b,F_SUBJECT_ID,"IMP-GENESIS-MVS-001");lgo_add_utf8(&b,F_PREDICATE,"write_count");lgo_add_u64(&b,F_VALUE_KIND,(u64)ValueKind::U64);Buffer o;lgo_finish(&b,&o,nullptr);auto st=graph_add_node(s,l,g,{o.data(),(u64)o.size()},nullptr);return st==Status::NodeExists?Status::Ok:st;}static Status add_lc001(ObjectStore*s,Ledger*l,GraphState*g){std::string evidence="EVD-OBS-GENESIS-RECEIVER-001-CLM-GENESIS-HARDCRASH-001";LgoBuilder b{};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::PRINCIPLE);lgo_add_utf8(&b,F_SEMANTIC_ID,"LC-001");lgo_add_u64(&b,F_REVISION,1);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_u64(&b,F_MATURITY,(u64)Maturity::L4_CROSS_VERIFIED);lgo_add_utf8(&b,F_SCOPE,"FUSE-LOGOS-normalized-canon");lgo_add_utf8(&b,F_VALUE_TEXT,"A system's claimed state must not outrank independently observable evidence of its actual state.");lgo_add_utf8(&b,F_REF_A_ID,evidence);lgo_add_utf8(&b,F_FALSIFICATION_CONDITION,"Revise if a legitimate outcome-relevant system class is found where an unobserved declaration is more authoritative than observable state.");lgo_add_utf8(&b,F_APPLICABILITY_BOUNDARY,"Systems whose relevant outcome state can be observed or independently evidenced.");Buffer o;lgo_finish(&b,&o,nullptr);auto st=graph_add_node(s,l,g,{o.data(),(u64)o.size()},nullptr);return st==Status::NodeExists?Status::Ok:st;}
Status run_mevs_acceptance(const std::filesystem::path&root){Digest256 abc=sha256({(const u8*)"abc",3});if(hex(abc)!="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")return Status::BadDigest;std::error_code ec;std::filesystem::remove_all(root,ec);std::filesystem::create_directories(root,ec);if(ec)return Status::IOError;ObjectStore s{};Ledger l{};GraphState g{};auto st=open_all(root,&s,&l,&g);if(st!=Status::Ok)return st;const std::string hist="LHF1\nsource_id=SRC-KH-1930-LOGOS-MEVS\nauthor=Arnold Krumm-Heller\ntitle=Logos, Mantram, Magia\nyear=1930\nwitness_id=WIT-KH-1930-LOGOS-MEVS-01\npassage_id=PAS-KH-1930-LOGOS-MEVS-001\nlocator=MEVS synthetic passage 001\nclaim_id=CLM-KH-LOGOS-MEVS-001\nsubject_id=SRC-KH-1930-LOGOS-MEVS\npredicate=historical_doctrine_statement\nclaim_class=HISTORICAL_DOCTRINE\nepistemic=REPORTED\nscope=historical-source-fixture\npayload=This synthetic fixture represents a historical doctrine claim about Logos and creative articulation.\n";const std::string gen="LGF1\nimplementation_id=IMP-GENESIS-MVS-001\ncourt_id=CRT-GENESIS-HARDCRASH-001\nscope=hosted-windows-canary-v1\nobs_receiver_id=OBS-GENESIS-RECEIVER-001\nreceiver_content=FUSE-GENESIS-NEW-V1\nobs_write_id=OBS-GENESIS-WRITECOUNT-001\nwrite_count=1\nobs_duplicate_id=OBS-GENESIS-DUPLICATE-001\nduplicate_second_effect=0\nclaim_id=CLM-GENESIS-HARDCRASH-001\n";CompilerCapsule hc{},gc{};if((st=ingest_historical(&s,&l,&g,{(const u8*)hist.data(),(u64)hist.size()},&hc))!=Status::Ok)return st;if((st=ingest_genesis(&s,&l,&g,{(const u8*)gen.data(),(u64)gen.size()},&gc))!=Status::Ok)return st;if((st=add_lc001(&s,&l,&g))!=Status::Ok)return st;if((st=add_controlled_claim(&s,&l,&g,"CLM-MEVS-WRITECOUNT-A",1,"hosted-windows-canary-v1","OBS-GENESIS-WRITECOUNT-001"))!=Status::Ok)return st;if((st=add_controlled_claim(&s,&l,&g,"CLM-MEVS-WRITECOUNT-B",2,"hosted-windows-canary-v1","OBS-GENESIS-WRITECOUNT-001"))!=Status::Ok)return st;if((st=add_controlled_claim(&s,&l,&g,"CLM-MEVS-WRITECOUNT-SCOPE-A",1,"hosted-windows-build-A","OBS-GENESIS-WRITECOUNT-001"))!=Status::Ok)return st;if((st=add_controlled_claim(&s,&l,&g,"CLM-MEVS-WRITECOUNT-SCOPE-B",2,"synthetic-negative-fixture","OBS-GENESIS-WRITECOUNT-001"))!=Status::Ok)return st;if((st=detect_contradictions(&g,&s,&l))!=Status::Ok)return st;u64 contradictions{};graph_count_type(g,NodeType::CONTRADICTION,&contradictions);if(contradictions!=1)return Status::InvariantViolation;Digest256 graph1{},canon1{},proof1{};if((st=verify_root(root,&graph1,&canon1,&proof1))!=Status::Ok)return st;if((st=ledger_open(root/"ledger"/"events.lgl",&l))!=Status::Ok)return st;if((st=graph_replay(&s,l,&g))!=Status::Ok)return st;u64 events_before{};ledger_count(l,&events_before);Digest256 before_reingest{};graph_root(g,&before_reingest);CompilerCapsule hc2{},gc2{};if((st=ingest_historical(&s,&l,&g,{(const u8*)hist.data(),(u64)hist.size()},&hc2))!=Status::Ok)return st;if((st=ingest_genesis(&s,&l,&g,{(const u8*)gen.data(),(u64)gen.size()},&gc2))!=Status::Ok)return st;u64 events_after{};ledger_count(l,&events_after);Digest256 after_reingest{};graph_root(g,&after_reingest);if(before_reingest!=after_reingest||events_before!=events_after)return Status::InvariantViolation;std::filesystem::remove_all(root/"projection",ec);std::filesystem::remove_all(root/"views",ec);Digest256 graph2{},canon2{},proof2{};if((st=verify_root(root,&graph2,&canon2,&proof2))!=Status::Ok)return st;if(graph1!=graph2||canon1!=canon2||proof1!=proof2)return Status::InvariantViolation;GraphState replay{};if((st=graph_replay(&s,l,&replay))!=Status::Ok)return st;Buffer cb;LgoObjectView cv{};if((st=graph_load_node(replay,s,"CLM-KH-LOGOS-MEVS-001",&cb,&cv))!=Status::Ok)return st;u64 ep{};if(lgo_get_u64(cv,F_EPISTEMIC_STATE,&ep)!=Status::Ok||ep!=(u64)Epistemic::REPORTED)return Status::EpistemicAmplification;Buffer gb;LgoObjectView gv{};if((st=graph_load_node(replay,s,"CLM-GENESIS-HARDCRASH-001",&gb,&gv))!=Status::Ok)return st;std::string sc;if(lgo_get_utf8(gv,F_SCOPE,&sc)!=Status::Ok||sc!="hosted-windows-canary-v1")return Status::ScopeMissing;std::filesystem::create_directories(root/"receipts",ec);u64 eventCount{};ledger_count(l,&eventCount);u64 objectCount=0;for(auto const&p:std::filesystem::recursive_directory_iterator(root/"objects"))if(p.is_regular_file())objectCount++;std::ofstream f(root/"receipts"/"mevs-receipt.json",std::ios::trunc);if(!f)return Status::IOError;f<<"{\n"<<"  \"schema\":\"LOGOS_MEVS_RECEIPT_V1\",\n"<<"  \"state\":\"LOGOS_MEVS_PROVEN_LOCAL\",\n"<<"  \"graph_court\":\"18_OF_18_REQUIRED\",\n"<<"  \"compiler_court\":\"20_OF_20_REQUIRED\",\n"<<"  \"historical_input_digest\":\""<<hex(hc.input_digest)<<"\",\n"<<"  \"genesis_input_digest\":\""<<hex(gc.input_digest)<<"\",\n"<<"  \"graph_root\":\""<<hex(graph2)<<"\",\n"<<"  \"canon_view_digest\":\""<<hex(canon2)<<"\",\n"<<"  \"proof_view_digest\":\""<<hex(proof2)<<"\",\n"<<"  \"contradiction_count\":1,\n"<<"  \"object_count\":"<<objectCount<<",\n"<<"  \"event_count\":"<<eventCount<<",\n"<<"  \"node_count\":"<<replay.nodes.size()<<",\n"<<"  \"edge_count\":"<<replay.edges.size()<<",\n"<<"  \"replay_graph_digest\":\""<<hex(graph2)<<"\",\n"<<"  \"replay_match\":true,\n"<<"  \"duplicate_ingest_match\":true,\n"<<"  \"network_required\":false,\n"<<"  \"truth_boundary\":\"Deterministic local fixture ingestion, provenance preservation, graph formation, controlled contradiction handling, replay and view regeneration only. No autonomous-research, historical-truth, production-scale or Canon-validity claim.\"\n"<<"}\n";return f?Status::Ok:Status::IOError;}
